import{_ as a,o as s,c as o,a2 as i}from"./chunks/framework.uPSHzigi.js";const u=JSON.parse('{"title":"Coach Poulpy","description":"","frontmatter":{},"headers":[],"relativePath":"CLAUDE.md","filePath":"CLAUDE.md"}'),n={name:"CLAUDE.md"};function d(t,e,r,l,c,h){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="coach-poulpy" tabindex="-1">Coach Poulpy <a class="header-anchor" href="#coach-poulpy" aria-label="Permalink to &quot;Coach Poulpy&quot;">​</a></h1><p>A training platform: Android and iOS apps first, guest-only and offline, with a server and website to come. One Kotlin Multiplatform core holds every decision about workouts; the apps only render and talk to hardware. The README maps the modules and how to run each part.</p><h2 id="read-before-you-work" tabindex="-1">Read before you work <a class="header-anchor" href="#read-before-you-work" aria-label="Permalink to &quot;Read before you work&quot;">​</a></h2><ul><li><code>CONTEXT.md</code>: the glossary. Name things with its terms in code, issues, tests and UI copy.</li><li><code>docs/adr/</code>: decisions that look odd without their reason. Read the ones touching your area; say so explicitly if your change contradicts one.</li><li><code>docs/architecture.md</code>: the overview, for anything spanning modules.</li><li><code>docs/design-system.md</code> and <code>docs/brand.md</code>: before any screen, colour, copy or Poulpy change.</li><li><code>CONTRIBUTING.md</code>: the issue-to-PR flow and labels.</li><li><code>docs/agents/roles.md</code>: the long-running role threads (Architect, Designer, Poulpy keeper, Translator, Maintainer), what each owns, and when to consult them and hand back.</li></ul><h2 id="prove-a-change-works" tabindex="-1">Prove a change works <a class="header-anchor" href="#prove-a-change-works" aria-label="Permalink to &quot;Prove a change works&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jvmTest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsTest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :server:test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # shared logic and server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-tokens.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # theme files match design/tokens.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-poulpy.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Poulpy drawings match their generator</span></span></code></pre></div><p>Android and iOS only build in CI (<code>.github/workflows/ci.yml</code>); a PR is done when CI is green. Bluetooth, sound, haptics, background running and installs need a real phone: label the issue <code>device-test</code> and say what to check.</p><h2 id="house-rules" tabindex="-1">House rules <a class="header-anchor" href="#house-rules" aria-label="Permalink to &quot;House rules&quot;">​</a></h2><ul><li>Logic goes in shared Kotlin with a test; Compose and SwiftUI code stays thin and mirrors the other platform.</li><li>Theme files and Poulpy drawings are generated: edit <code>design/tokens.json</code> or <code>design/build-poulpy.mjs</code> and regenerate.</li><li>Mockups are plain HTML in <code>design/mockups/</code> (ADR 0016), styled only with <code>var(--cp-*)</code> from the token CSS, <code>shared/mockup.css</code> and <code>design/poulpy/*.svg</code>. A new screen or redesign starts in <code>drafts/</code>; nothing is built until a PR moves it to <code>agreed/</code>. The claude.ai canvas is scratch only.</li><li>Every user-facing string exists in English and French (Android <code>values</code> and <code>values-fr</code>, iOS <code>en.lproj</code> and <code>fr.lproj</code>, shared <code>Labels</code>).</li><li>Catalog slugs never change; set <code>&quot;retired&quot;: true</code> instead of deleting, and raise <code>version</code>.</li><li>Poulpy is never guilt: pain or rehab always shows the blue side, and errors are crimson with an icon, never ember.</li><li>A schema change is a new SQLDelight migration; existing phones keep their data.</li><li>Branches are named <code>&lt;type&gt;/&lt;issue-number&gt;-&lt;short-description&gt;</code> in English (<code>feat/21-training-plans</code>, or <code>docs/brand-decisions</code> with no issue); types <code>feat</code>, <code>fix</code>, <code>docs</code>, <code>chore</code>, <code>design</code>. Never a random suffix, session id or <code>claude/</code> prefix, even if a tool suggests one.</li></ul><h2 id="agent-skills" tabindex="-1">Agent skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent skills&quot;">​</a></h2><h3 id="issue-tracker" tabindex="-1">Issue tracker <a class="header-anchor" href="#issue-tracker" aria-label="Permalink to &quot;Issue tracker&quot;">​</a></h3><p>Issues live in GitHub Issues on <code>tkint/coach-poulpy</code>. See <code>docs/agents/issue-tracker.md</code>.</p><h3 id="triage-labels" tabindex="-1">Triage labels <a class="header-anchor" href="#triage-labels" aria-label="Permalink to &quot;Triage labels&quot;">​</a></h3><p>The default five triage roles, label names unchanged. See <code>docs/agents/triage-labels.md</code>.</p><h3 id="domain-docs" tabindex="-1">Domain docs <a class="header-anchor" href="#domain-docs" aria-label="Permalink to &quot;Domain docs&quot;">​</a></h3><p>Single context: <code>CONTEXT.md</code> and <code>docs/adr/</code> at the root. See <code>docs/agents/domain.md</code>.</p>`,16)])])}const g=a(n,[["render",d]]);export{u as __pageData,g as default};
